function InvitationPreview() {
  const [variables, setVariables] = useState(false);
  const [clicked, setClicked] = useState(false);
  const [knownRecipient, setKnownRecipient] = useState(true);
  const app = variables ? '{{app.name}}' : 'SpendGuru';
  // Preview values only. Production greeting is resolved by Identity from the persisted profile and reviewed vocative dictionary.
  const greeting = variables ? '{{greeting}}' : knownRecipient ? 'Cześć, Marku!' : 'Cześć!';
  const inviterName = variables ? '{{invitation.inviter_name}}' : 'Ada Kowalska';
  const inviterEmail = variables ? '{{invitation.inviter_email}}' : 'ada@example.test';
  const organisation = variables ? '{{organization.name}}' : 'PORR S.A.';
  const showPreview = (event: React.MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault();
    setClicked(true);
  };
  return <main {...deliveryAttributes("464435360387190784:80438f998d31f6")} className="srm-email-preview invitation-preview" data-design-source="464300259384918016" data-design-revision="464300259384918017" data-email-kind="invitation" data-email-avatar={EMAIL_AVATAR_VARIANT}>
    <header {...deliveryAttributes("464435360387190784:75cb403b4cf04f")} className="email-preview-controls" aria-label="Ustawienia podglądu wiadomości">
