      <div {...deliveryAttributes("464435360387190784:80da21faa64007")} className="email-preview-actions">
        <button {...deliveryAttributes("464435360387190784:67e5fe48cd33e6")} className="email-data-toggle" type="button" aria-pressed={variables} onClick={deliveryHandler("464435360387190784:3084b54cf348f5", () => setVariables(!variables))}><DeliveryValue id="464435360387190784:3bf6a938a12546">{variables ? 'Pokaż przykład' : 'Pokaż zmienne'}</DeliveryValue></button>
        <button className="email-data-toggle" type="button" aria-pressed={knownRecipient} onClick={() => setKnownRecipient(!knownRecipient)}>{knownRecipient ? 'Odbiorca: Marek → Marku' : 'Odbiorca: tylko e-mail'}</button>
        <CanonThemeSwitch />
      </div>
    </header>

    <article {...deliveryAttributes("464435360387190784:ca375eeb29ac5a")} className="porr-email" aria-label="Twoje zaproszenie do SpendGuru">
      <header {...deliveryAttributes("464435360387190784:065a35316917c5")} className="email-brand-header">
        <div {...deliveryAttributes("464435360387190784:c6c24ef9b95e7e")} className="email-brand-row">
          <span className="email-spendguru-brand" role="img" aria-label="SpendGuru" data-brand-asset="SRM-L01" data-brand-dark-source-sha256="dd951312903ec8c21d60d5a96a3d6d1f44bf86dca5b7735f8730439c46b25eaf"><img {...deliveryAttributes("464435360387190784:00c24fe6a322a7")} className="email-spendguru-logo" src={assets + 'afb9683d055c12646577d38072041bb4a19daa9faf56c9d93a4e129d05bc183b.png'} alt="" aria-hidden="true" width="144" height="46" /><img className="email-spendguru-white" src="https://storage.googleapis.com/storage.magicpath.ai/component-assets/460628347660177408/465813315344568320/dd951312903ec8c21d60d5a96a3d6d1f44bf86dca5b7735f8730439c46b25eaf.svg" alt="" aria-hidden="true" width="144" height="46" /></span>
          <span {...deliveryAttributes("464435360387190784:c9849975ee2f35")} className="email-brand-rule" aria-hidden="true" />
          <img {...deliveryAttributes("464435360387190784:0641c2c9c38211")} className="email-porr-logo" src={assets + 'bc8eacde8abec8ccafe8db4696f8f78b5a312dd52967e283437622675dacb25d.png'} alt="PORR" width="52" height="33" />
        </div>
      </header>

      <div {...deliveryAttributes("464435360387190784:64533b9ce97d03")} className="email-main">
        <h1 {...deliveryAttributes("464435360387190784:56ac2d24accfed")}>Twoje zaproszenie do <DeliveryValue id="464435360387190784:c278d28ee78720">{app}</DeliveryValue></h1>
        <table {...deliveryAttributes("464435360387190784:8f02593a6c2820")} className="email-conversation" role="presentation" cellPadding="0" cellSpacing="0"><tbody {...deliveryAttributes("464435360387190784:6ce7062425f3de")}><tr {...deliveryAttributes("464435360387190784:55fecef1d33340")}>
          <td {...deliveryAttributes("464435360387190784:1a044ef3693fe4")} className="email-avatar-cell">
            <img {...deliveryAttributes("464435360387190784:028b7485b68606")} className="email-avatar" src={EMAIL_AVATAR_SOURCES[EMAIL_AVATAR_VARIANT]} alt={EMAIL_AVATAR_VARIANT === 'female' ? 'SpendGuru — awatar żeński' : 'SpendGuru — awatar męski'} width="58" height="58" />
          </td>
          <td {...deliveryAttributes("464435360387190784:834115cc84d00b")} className="email-message-cell">
            <p {...deliveryAttributes("464435360387190784:4d5e32328838cd")} className="email-sender">SpendGuru </p>
            <div {...deliveryAttributes("464435360387190784:3671efb781782d")} className="email-bubble">
              <p {...deliveryAttributes("464435360387190784:ce614fced420bb")} className="email-greeting">{greeting}</p>
              <p {...deliveryAttributes("464435360387190784:ea99c433d3da9b")} className="email-message">Do {app} zaprasza Cię <strong>{inviterName}</strong> ({inviterEmail}) z organizacji <strong>{organisation}</strong>.</p>
              <p className="email-message">Dołącz do wspólnej przestrzeni zakupowej. Po potwierdzeniu konta wybierzesz swoje kategorie zakupowe. Dane organizacji są już przygotowane.</p>
              <p {...deliveryAttributes("464435360387190784:351279f28df6fe")} className="email-invitation-expiry">Zaproszenie wygaśnie za <strong {...deliveryAttributes("464435360387190784:272b41a2e69dfc")}><DeliveryValue id="464435360387190784:3bbf2dc529449b">{variables ? '{{invitation.expires_in_days}}' : '7'}</DeliveryValue> dni</strong>.</p>
