/* PORR email presentation: SRM FND-05 visual tokens; avatar and brand assets from the approved registration view.
   Preview controls are outside the email. Exported email must use inline styles / Revolvapp, with no scripts.
   Code, text and bubble remain real text/HTML, never a screenshot. */
.srm-email-preview{min-height:100dvh;background:var(--page,#F8F9FA);color:var(--ink,#003366);padding:28px 24px 24px;font-family:Arial,Helvetica,sans-serif;box-sizing:border-box}
.srm-email-preview *{box-sizing:border-box}
.email-preview-controls{max-width:600px;margin:0 auto 22px;display:flex;align-items:center;justify-content:space-between;gap:16px}
.email-preview-kicker{font-size:9px;letter-spacing:1.5px;color:var(--muted,#526A82)}
.email-preview-controls p{font-size:12px;margin:5px 0 0;color:var(--muted,#526A82)}
.email-preview-actions{display:flex;align-items:center;gap:12px}
.email-preview-actions .srm-theme-switch button{width:29px;padding:0}
.email-preview-actions .srm-theme-switch button span{display:none}
.email-data-toggle{font:12px Arial,Helvetica,sans-serif;background:transparent;border:0;padding:7px 0;color:var(--brand,#005A9C);cursor:pointer;white-space:nowrap}
.email-data-toggle:focus-visible{outline:2px solid var(--brand-light,#66B2FF);outline-offset:3px;border-radius:3px}
.email-data-toggle[aria-pressed=true]{font-weight:700}
.porr-email{max-width:600px;margin:auto;background:var(--surface,#fff);border:1px solid var(--faint-line,#E7EDF2);border-radius:18px;overflow:hidden;box-shadow:0 9px 34px rgba(0,35,65,.035)}
.email-brand-header{padding:32px 36px 0}
.email-brand-row{display:flex;align-items:center;gap:22px;width:max-content;max-width:100%}
.email-brand-row img{display:block;object-fit:contain;height:auto}
.email-spendguru-logo{width:144px}
.email-porr-logo{width:52px}
.email-brand-rule{height:28px;width:1px;background:var(--line,#D6E0E9)}
.email-pilot-label{font-size:10px;line-height:1.5;letter-spacing:1.3px;text-transform:uppercase;color:var(--muted,#526A82);margin:22px 0 0}
.email-main{padding:26px 36px 0}
.email-main h1{font-size:28px;line-height:1.2;letter-spacing:-.7px;font-weight:600;color:var(--ink,#003366);margin:0}
.email-intro{font-size:12px;line-height:1.5;color:var(--muted,#526A82);margin:10px 0 32px}
.email-conversation{width:100%;table-layout:fixed;border-collapse:collapse;border:0}
.email-avatar-cell{width:76px;vertical-align:top;padding:24px 18px 0 0;border:0}
.email-avatar{width:58px;height:58px;display:block;border-radius:50%;border:1px solid #D2B48C;padding:2px;background:#fff;object-fit:cover}
.email-message-cell{vertical-align:top;min-width:0;padding:0;border:0}
.email-sender{font-size:12px;line-height:1.5;margin:0 0 9px;color:var(--ink,#003366);font-weight:600}
.email-sender span{font-weight:400;color:var(--muted,#526A82)}
.email-bubble{background:var(--blue-soft,#EAF3FF);border:1px solid var(--line,#D6E0E9);border-radius:5px 19px 19px 19px;padding:22px 24px 23px}
.email-greeting,.email-message{font-size:14px;line-height:1.6;margin:0;color:var(--text,#294D70)}
.email-message{margin-top:10px}
.email-otp{font-size:38px;line-height:1.2;letter-spacing:7px;margin:24px 0 20px;font-weight:600;color:var(--ink,#003366);font-variant-numeric:tabular-nums;white-space:nowrap}
.email-otp.is-variable{font-family:monospace;font-size:27px;letter-spacing:0;white-space:normal;overflow-wrap:anywhere}
.email-instruction{font-size:13px;line-height:1.65;margin:0;color:var(--text,#294D70)}
.email-code-note{font-size:12px;line-height:1.65;color:var(--muted,#526A82);margin:16px 0 0 2px}
.email-request-note{border-top:1px solid var(--faint-line,#E7EDF2);margin-top:30px;padding:23px 0 25px}
.email-request-note h2{font-size:13px;line-height:1.5;margin:0 0 5px;font-weight:600;color:var(--text,#294D70)}
.email-request-note p{font-size:12px;line-height:1.65;color:var(--muted,#526A82);margin:0}
.email-request-note .email-request-meta{font-size:11px;line-height:1.7;margin-top:14px;overflow-wrap:anywhere}
.email-request-meta span{color:var(--text,#294D70)}
.email-footer{padding:20px 36px 24px;background:var(--page,#F8F9FA);border-top:1px solid var(--faint-line,#E7EDF2)}
.email-footer p{font-size:11px;line-height:1.7;margin:0;color:var(--muted,#526A82)}
.email-footer p+p{font-size:10px;margin-top:3px}
.email-preview-note{max-width:600px;margin:16px auto 0;color:var(--muted,#526A82);font-size:10px;line-height:1.5;text-align:center}

@media(max-width:520px){.srm-email-preview{padding:20px 12px}.email-preview-controls{gap:10px;align-items:start}.email-preview-actions{gap:8px;flex-wrap:wrap;justify-content:flex-end}.email-preview-kicker{font-size:8px}.email-preview-controls p{font-size:10px}.email-data-toggle{font-size:11px}.email-brand-header{padding:26px 20px 0}.email-main{padding:22px 20px 0}.email-main h1{font-size:25px}.email-intro{margin-bottom:27px}.email-avatar-cell{width:48px;padding-right:10px;padding-top:25px}.email-avatar{width:38px;height:38px}.email-sender{font-size:11px}.email-bubble{padding:18px 16px}.email-greeting,.email-message{font-size:13px}.email-otp{font-size:32px;letter-spacing:5px;margin:22px 0 18px}.email-otp.is-variable{font-size:22px}.email-instruction{font-size:12px}.email-code-note{font-size:11px}.email-footer{padding:18px 20px 22px}}
@media(max-width:350px){.email-otp{font-size:28px;letter-spacing:3px}.email-otp.is-variable{font-size:19px}.email-bubble{padding:16px 12px}.email-sender span{display:none}}

/* Shared email chrome: exact Profitia footer and assistant preference variants. */
.email-conversation{margin-top:30px}
.email-footer .email-footer-copyright{font-size:11px;line-height:1.7;margin:0 0 16px}
.email-footer .email-footer-company{font-size:12px;line-height:1.6;margin:0;color:var(--text,#294D70);font-weight:600}
.email-footer .email-footer-services{font-size:11px;line-height:1.75;margin:12px 0;color:var(--muted,#526A82)}
.email-footer .email-footer-address{font-size:11px;line-height:1.7;margin:0;color:var(--muted,#526A82)}
@media(max-width:520px){.email-conversation{margin-top:25px}.email-footer .email-footer-services{font-size:11px}}

/* SRM-L01: retain the original light frame; overlay the approved white SVG.
   The original image owns layout in both modes, so the brand never jumps. */
.email-spendguru-brand{position:relative;display:block;flex:none;width:144px;line-height:0}
.email-brand-row .email-spendguru-white{display:none;position:absolute;inset:0;width:100%;height:100%;object-fit:contain}
:root[data-srm-theme=dark] .email-spendguru-brand>.email-spendguru-logo{visibility:hidden}
:root[data-srm-theme=dark] .email-spendguru-brand>.email-spendguru-white{display:block}

